import{_ as s,C as i,o as t,c as n,a2 as r,b as l,w as a,a as h,E as d,a3 as c}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse('{"title":"File Manager Guide","description":"How Trash Bin Pro works inside the Pterodactyl file manager — the Trash view, quota-aware deletes, restoring files, and emptying the trash.","frontmatter":{"title":"File Manager Guide","description":"How Trash Bin Pro works inside the Pterodactyl file manager — the Trash view, quota-aware deletes, restoring files, and emptying the trash."},"headers":[],"relativePath":"trash-bin-pro/user-guide/file-manager.md","filePath":"trash-bin-pro/user-guide/file-manager.md","lastUpdated":1785521056000}'),g={name:"trash-bin-pro/user-guide/file-manager.md"};function m(u,e,f,p,b,w){const o=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=r('<h1 id="file-manager-guide" tabindex="-1">File Manager Guide <a class="header-anchor" href="#file-manager-guide" aria-label="Permalink to &quot;File Manager Guide&quot;">​</a></h1><p>Trash Bin Pro integrates directly into the stock Pterodactyl file manager. Deleted files are moved to a hidden <code>/.trash</code> folder on the server instead of being removed, and can be restored until their retention window expires.</p><hr><h2 id="opening-the-trash" tabindex="-1">Opening the Trash <a class="header-anchor" href="#opening-the-trash" aria-label="Permalink to &quot;Opening the Trash&quot;">​</a></h2><p>The <code>/.trash</code> folder <strong>never appears in normal directory listings</strong> — it is filtered out of the UI entirely, so it cannot be clicked, renamed, or deleted by accident.</p><p>Instead, a dedicated <strong>Trash</strong> button sits in the file manager toolbar, next to Upload and New File. Clicking it navigates to <code>#/.trash</code>.</p><div class="tip custom-block"><p class="custom-block-title">Subusers</p><p>The Trash button is only shown to users with the <strong><code>trashbinpro.access</code></strong> permission (server <strong>Users</strong> tab → <strong>Trash Bin Pro → Access</strong>). The server owner always has it.</p></div><h2 id="the-trash-view" tabindex="-1">The Trash view <a class="header-anchor" href="#the-trash-view" aria-label="Permalink to &quot;The Trash view&quot;">​</a></h2><p>The trash view looks like a normal directory, with a few deliberate differences:</p><ul><li>The breadcrumb renders <strong>Trash</strong> instead of <code>.trash</code>.</li><li>Each row shows a <strong>trash icon</strong>, the file&#39;s <strong>original path</strong> as its name (e.g. <code>plugins/broken-plugin.jar</code>), and its <strong>real size</strong>.</li><li>A banner at the top reads: <em>&quot;Files here are permanently deleted after their retention window.&quot;</em></li><li>The create actions — <strong>New Directory, Upload, New File</strong> — are hidden. Nothing new can be placed into the trash by hand.</li><li>Rows are <strong>not clickable</strong>: you cannot open or navigate into a trashed item.</li><li>Selecting rows tracks their numeric <strong>trash IDs</strong> instead of file names — the select-all checkbox selects every trash ID in the view, which is what powers mass restore and mass delete.</li></ul><h2 id="deleting-files-move-to-trash" tabindex="-1">Deleting files (move to trash) <a class="header-anchor" href="#deleting-files-move-to-trash" aria-label="Permalink to &quot;Deleting files (move to trash)&quot;">​</a></h2><p>Outside the trash, clicking <strong>Delete</strong> on a file or directory does not delete it immediately. The UI first checks the server&#39;s trash quota and then shows one of three dialogs:</p>',12)),(t(),l(c,null,{default:a(()=>[d(o,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BClick%20Delete%5D%20--%3E%20B%7BFetch%20trash%20quota%7D%0A%20%20%20%20B%20--%3E%7Cquota%20enabled%20%26%20cap%20%3E%200%7C%20C%7BFile%20size%20%3E%20cap%3F%7D%0A%20%20%20%20B%20--%3E%7Cno%20cap%20%2F%20fetch%20failed%7C%20F%0A%20%20%20%20C%20--%3E%7Cyes%7C%20D%5B%22Delete%20Permanently%20dialog%3Cbr%2F%3Erequires%20acknowledgement%20checkbox%22%5D%0A%20%20%20%20C%20--%3E%7Cno%7C%20E%7Bused%20%2B%20file%20size%20%3E%20cap%3F%7D%0A%20%20%20%20E%20--%3E%7Cyes%7C%20G%5B%22Trash%20Bin%20Full%20dialog%3Cbr%2F%3Edelete%20is%20blocked%22%5D%0A%20%20%20%20E%20--%3E%7Cno%7C%20F%5B%22Move%20to%20Trash%20confirm%3Cbr%2F%3Ementions%20retention%20hours%22%5D%0A%20%20%20%20D%20--%3E%7Cconfirmed%20with%20permanent%20flag%7C%20H%5BFile%20hard-deleted%2C%20skips%20trash%5D%0A%20%20%20%20F%20--%3E%7Cconfirmed%7C%20I%5B%22File%20moved%20to%20%2F.trash%3Cbr%2F%3Erestorable%20until%20retention%20expires%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<ul><li><strong>Normal case</strong> — a <em>Move to Trash</em> confirmation that tells you the retention window: <em>&quot;…will be moved to the Trash and automatically deleted after {retention}h.&quot;</em></li><li><strong>File larger than the cap</strong> — a <em>Delete Permanently</em> dialog. The danger button stays disabled until you tick the checkbox: <em>&quot;I understand this file will be permanently deleted and cannot be recovered.&quot;</em> Confirming sends the delete with the <code>permanent</code> flag, so the file skips the trash entirely.</li><li><strong>Trash full</strong> — a <em>Trash Bin Full</em> dialog: <em>&quot;The Trash Bin is full. Delete some files from the Trash and try again.&quot;</em> There is no confirm button — the delete is blocked until you free space.</li></ul><div class="info custom-block"><p class="custom-block-title">The same checks run server-side</p><p>If the quota changes between the dialog and the request, the API still enforces it and returns <code>409</code> with a <code>FileTooLargeForTrash</code> or <code>TrashBinFull</code> error. See the <a href="./api#quota-errors-409-conflict">API Reference</a>.</p></div><h2 id="restoring-files" tabindex="-1">Restoring files <a class="header-anchor" href="#restoring-files" aria-label="Permalink to &quot;Restoring files&quot;">​</a></h2><p>Inside the trash view, each row&#39;s context menu is reduced to two actions: <strong>Restore</strong> and <strong>Delete Permanently</strong> (rename, move, chmod, copy, archive, and download are not offered for trash entries).</p><ul><li><strong>Restore</strong> (context menu, requires <code>trashbinpro.access</code>) — returns the file to its original path.</li><li><strong>Mass restore</strong> — select several rows and click <strong>Restore</strong> in the mass action bar.</li></ul><p>If something already exists at the original path, the restored file is renamed with a suffix: <code>name (restored)</code>, then <code>name (restored 2)</code>, and so on — restoring never overwrites an existing file.</p><h2 id="deleting-from-trash" tabindex="-1">Deleting from trash <a class="header-anchor" href="#deleting-from-trash" aria-label="Permalink to &quot;Deleting from trash&quot;">​</a></h2><p><strong>Delete Permanently</strong> on a trash row (or <strong>Delete</strong> in the mass action bar) removes the selected entries for good — the files are deleted from <code>/.trash</code> on the daemon and their tracking rows are removed. The confirmation dialog makes this explicit: <em>&quot;Permanently delete N file(s)? This cannot be undone.&quot;</em></p><h2 id="emptying-the-trash" tabindex="-1">Emptying the trash <a class="header-anchor" href="#emptying-the-trash" aria-label="Permalink to &quot;Emptying the trash&quot;">​</a></h2><p>The mass action bar inside the trash view has an <strong>Empty Trash</strong> button that permanently deletes <strong>every</strong> entry for the server in one call.</p><div class="danger custom-block"><p class="custom-block-title">Bypasses retention</p><p>Empty Trash ignores the retention window — files are deleted immediately even if they were trashed seconds ago. There is no way to recover them afterwards.</p></div><h2 id="protections-built-in" tabindex="-1">Protections built in <a class="header-anchor" href="#protections-built-in" aria-label="Permalink to &quot;Protections built in&quot;">​</a></h2><p>Several guards keep the trash folder itself safe:</p><ul><li><code>/.trash</code> is filtered out of every listing, so it can never be selected or targeted through the UI.</li><li>Mass-delete requests silently exclude <code>.trash</code> even if a stale selection somehow contains it.</li><li>The rename/move modal <strong>silently refuses</strong> any operation whose target is <code>.trash</code> or a path inside it — the dialog simply closes without submitting.</li><li>Server-side, the API rejects any attempt to trash the trash directory itself (a <code>root</code> of <code>.trash</code>/<code>/.trash</code> or a path under it), so the protection cannot be bypassed with a hand-crafted request.</li></ul>',14))])}const v=s(g,[["render",m]]);export{y as __pageData,v as default};
